ValidationRule.errorConditionFormula:
AND( $Setup.Salesforce_Library_Settings__c.Disable_VRs__c = false, NOT( ISNEW() ), OR( RecordType.DeveloperName = 'Customer_Complaint', RecordType.DeveloperName = 'Non_Customer_Complaint' ),
AND( ISPICKVAL(Status, 'Provisionally Closed'), OR( ISBLANK(TEXT(IDR_Complaint_Outcome_Offered__c)), ISBLANK(IDR_Description_of_Outcome_Offered__c) ) )
)
